CustomField.formula:
IF(
OR(

/* Logged in user is the Auditor */
TPB_AuditorId__c = $User.Id,

/* NSM coverage via Auditor parent territory */
AND(
    NOT(ISBLANK($User.TPB_Territory__c)),
    TPB_AuditorId__r.TPB_Parent_Territory__c = $User.TPB_Territory__c
),

/* Directors (NSD) whose region prefix matches */
AND(
    $User.Title = "NSD",
    LEFT($User.Territory_Id__c,2) = LEFT(TPB_AuditorId__r.Territory_Id__c,2)
),

/* Admin override */
$Profile.Name = "System Administrator",

/* Executive role */
$UserRole.Name = "Executive"

),
1,
0
)
